WITH joined AS (SELECT e.*, p.segment, p.email, p.city FROM subscriptions e LEFT JOIN customers p ON e.customer_id <=> p.id) SELECT id, customer_id, start_date, end_date, monthly_fee, segment, email, city, CASE WHEN segment RLIKE '^(Corporate|Consumer)$' THEN 'GROUP_A' WHEN segment RLIKE '^(SMB)$' THEN 'PRIORITY' ELSE 'GROUP_B' END AS segment_zone FROM joined ORDER BY segment NULLS LAST;
